/**
 * One-time import of the legacy `user_profile` managed block into the
 * structured ontology.
 *
 * The old tool wrote free-text, dated bullets into `<DSH_HOME>/AGENTS.md`.
 * This module only understands that format and the most explicit Chinese
 * patterns; anything it cannot map is preserved as a dated `note` fact rather
 * than guessed into a hard constraint. The caller keeps a backup and only
 * clears the block when every line was imported.
 */

export const LEGACY_BEGIN = "<!-- dsh:user-profile:begin -->";
export const LEGACY_END = "<!-- dsh:user-profile:end -->";

/**
 * Parse the managed block, oldest first.
 * @param {string} body - whole AGENTS.md.
 * @returns {{date: string, text: string}[]} facts.
 */
export function parseLegacyFacts(body) {
	const start = body.indexOf(LEGACY_BEGIN);
	if (start < 0) return [];
	const from = start + LEGACY_BEGIN.length;
	const end = body.indexOf(LEGACY_END, from);
	if (end < 0) return [];
	const facts = [];
	for (const line of body.slice(from, end).split("\n")) {
		const trimmed = line.trim();
		if (!trimmed.startsWith("- ")) continue;
		const dated = /^-\s+(\d{4}-\d{2}-\d{2})\s+[—-]\s+(.*)$/.exec(trimmed);
		if (dated !== null) {
			facts.push({ date: dated[1], text: dated[2].trim() });
			continue;
		}
		const bare = /^-\s+(.*)$/.exec(trimmed);
		if (bare !== null && bare[1].trim().length > 0) facts.push({ date: "", text: bare[1].trim() });
	}
	return facts;
}

/**
 * Remove the managed block and everything after an unterminated block; keep
 * the user's prose exactly as it was.
 * @param {string} body - whole AGENTS.md.
 * @returns {string} body without the managed block.
 */
export function stripLegacyBlock(body) {
	const start = body.indexOf(LEGACY_BEGIN);
	if (start < 0) return body;
	const end = body.indexOf(LEGACY_END, start);
	if (end < 0) return body.slice(0, start);
	const after = end + LEGACY_END.length;
	return `${body.slice(0, start)}${body.slice(after).replace(/^\n+/, "\n")}`.trimEnd() + "\n";
}

/**
 * Map one free-text bullet to one ontology assertion. Deliberately
 * conservative: only explicit patterns become hard constraints; everything
 * else becomes a dated `note` so it is preserved and queryable, not injected.
 * @param {string} text - bullet text.
 * @returns {{predicate: string, object: string, qualifier?: string}} assertion.
 */
export function mapLegacyFact(text) {
	const raw = String(text ?? "").trim();
	const note = { predicate: "note", object: raw.slice(0, 500) };
	if (raw.length === 0) return note;
	let match;
	if ((match = /(?:我的)?(?:名字|姓名)(?:是|叫|[:：])?\s*([^，。；;,\s]+)/.exec(raw)) !== null) {
		return { predicate: "name", object: match[1] };
	}
	if ((match = /^我?叫\s*([^，。；;,\s]+)/.exec(raw)) !== null) {
		return { predicate: "name", object: match[1] };
	}
	if ((match = /(?:对)?([^，。；;,\s]+?)\s*过敏/.exec(raw)) !== null) {
		return { predicate: "allergy", object: match[1] };
	}
	if ((match = /(?:不吃|忌口|讨厌)\s*([^，。；;,]+)/.exec(raw)) !== null) {
		return { predicate: "avoids", object: match[1].trim() };
	}
	if (/素食|吃素|纯素/.test(raw)) return { predicate: "diet", object: "素食" };
	if (/清真/.test(raw)) return { predicate: "diet", object: "清真" };
	if ((match = /(?:说|用|讲)\s*(中文|汉语|英文|英语|日语|韩语)/.exec(raw)) !== null) {
		return { predicate: "language", object: match[1] };
	}
	if ((match = /(?:时区|timezone)[:：]?\s*([A-Za-z_+\-/]+)/i.exec(raw)) !== null) {
		return { predicate: "timezone", object: match[1] };
	}
	if ((match = /(?:住在|定居在)\s*([^，。；;,]+)/.exec(raw)) !== null) {
		return { predicate: "city", object: match[1].trim() };
	}
	const relation = /(?:我的)?(妈妈|爸爸|父亲|母亲|儿子|女儿|妻子|丈夫|老婆|老公)(?:是|叫)\s*([^，。；;,]+)/.exec(raw);
	if (relation !== null) {
		const roles = {
			"妈妈": "mother", "母亲": "mother", "爸爸": "father", "父亲": "father",
			"儿子": "son", "女儿": "daughter", "妻子": "wife", "老婆": "wife",
			"丈夫": "husband", "老公": "husband",
		};
		return { predicate: "relation", object: relation[2].trim(), qualifier: roles[relation[1]] };
	}
	return note;
}
